const DATA = {"anchored":[{"file":"apps/web-storefront/components/AccountShell.tsx","what":"the menu stays on Support and Report a bug","done":"export function menuPageOf(","pairs":[["\n/** Whether this address is one of the menu's pages (or a page inside one: an order, a return, a vehicle): the menu stays on all of them. */\nexport function inAccountMenu(path: string): boolean {\n","\n// Pages reached from one of the menu's pages: the menu stays on them too, with that page marked (Contact us leads to Support and to Report a bug).\nconst REACHED_FROM: Array<[string, string]> = [[\"/support\", \"/contact\"], [\"/report-bug\", \"/contact\"]];\nconst under = (path: string, href: string) => path === href || path.startsWith(`${href}/`);\n\n/** The menu's page this address belongs to: the page itself, the page it is inside (an order, a return), or the page it is reached from; null elsewhere. */\nexport function menuPageOf(path: string): string | null {\n  const own = ITEMS.filter(([href]) => under(path, href)).sort((a, b) => b[0].length - a[0].length)[0];\n  if (own) return own[0];\n  const from = REACHED_FROM.find(([prefix]) => under(path, prefix));\n  return from ? from[1] : null;\n}\n\n/** Whether the menu stays on this address: every page it lists, the pages inside them, and the pages reached from them. */\nexport function inAccountMenu(path: string): boolean {\n"],["export function inAccountMenu(path: string): boolean {\n  return ITEMS.some(([href]) => path === href || path.startsWith(`${href}/`));\n}\n","export function inAccountMenu(path: string): boolean {\n  return menuPageOf(path) !== null;\n}\n"],["  const ownFrame = here === \"/account\" || here.startsWith(\"/account/\");\n  const item = ITEMS.find(([href]) => href === here);      // the header box: on the menu's own pages (an order or a return keeps its own title)\n  return (\n","  const ownFrame = here === \"/account\" || here.startsWith(\"/account/\");\n  const item = ITEMS.find(([href]) => href === here);\n  const marked = menuPageOf(here);      // the menu's page to mark: this page, or the one it belongs to      // the header box: on the menu's own pages (an order or a return keeps its own title)\n  return (\n"],["            <li key={href}>\n              <Link href={href} aria-current={here === href ? \"page\" : undefined} className={`flex min-h-11 items-center rounded-lg px-3 text-[15px] font-semibold ${here === href ? \"bg-navy text-white\" : \"text-ink hover:bg-chalk\"}`}>{t(key)}</Link>\n            </li>\n","            <li key={href}>\n              <Link href={href} aria-current={here === href ? \"page\" : marked === href ? \"true\" : undefined} className={`flex min-h-11 items-center rounded-lg px-3 text-[15px] font-semibold ${marked === href ? \"bg-navy text-white\" : \"text-ink hover:bg-chalk\"}`}>{t(key)}</Link>\n            </li>\n"]]},{"file":"apps/web-storefront/components/AccountShell.test.tsx","what":"tests","done":"the menu also stays on the pages reached from it","pairs":[["\nimport AccountShell, { inAccountMenu } from \"./AccountShell\";\nimport { LangProvider } from \"./LangProvider\";\n","\nimport AccountShell, { inAccountMenu, menuPageOf } from \"./AccountShell\";\nimport { LangProvider } from \"./LangProvider\";\n"],["    expect(screen.getByRole(\"navigation\")).toBeInTheDocument();\n  });\n","    expect(screen.getByRole(\"navigation\")).toBeInTheDocument();\n  });\n});\n\ndescribe(\"the menu also stays on the pages reached from it\", () => {\n  it(\"Support, a ticket and Report a bug keep the menu, with Contact us marked; a page inside one marks its page\", () => {\n    for (const p of [\"/support\", \"/support/T-1\", \"/report-bug\"]) expect(inAccountMenu(p), p).toBe(true);\n    for (const [p, page] of [[\"/support\", \"/contact\"], [\"/support/T-1\", \"/contact\"], [\"/report-bug\", \"/contact\"], [\"/orders/abc\", \"/orders\"], [\"/account/loyalty\", \"/account/loyalty\"], [\"/supportx\", null]] as const) expect(menuPageOf(p), p).toBe(page);\n    m.path.current = \"/ar/support\"; show(\"ar\");\n    expect(screen.getByRole(\"navigation\")).toBeInTheDocument();\n    expect(screen.getByRole(\"link\", { name: \"تواصل معنا\" }).getAttribute(\"aria-current\")).toBe(\"true\");\n    expect(screen.queryByTestId(\"account-page-header\")).not.toBeInTheDocument();      // the page keeps its own title\n  });\n"]]},{"file":"apps/web-storefront/lib/i18n.ts","what":"\"Choose a file\" / \"No file chosen\" in English and Arabic","done":"no_file_chosen:","pairs":[["  account_sidebar: \"Account sections\",\n  acct_desc_account: \"Your details, your numbers and your membership at a glance.\",\n","  account_sidebar: \"Account sections\",\n  choose_file: \"Choose a file\",\n  no_file_chosen: \"No file chosen\",\n  acct_desc_account: \"Your details, your numbers and your membership at a glance.\",\n"],["  account_sidebar: \"أقسام الحساب\",\n  acct_desc_account: \"بياناتك وأرقامك وعضويتك في مكان واحد.\",\n","  account_sidebar: \"أقسام الحساب\",\n  choose_file: \"اختر ملفًا\",\n  no_file_chosen: \"لم يتم اختيار ملف\",\n  acct_desc_account: \"بياناتك وأرقامك وعضويتك في مكان واحد.\",\n"]]},{"file":"apps/web-storefront/app/report-bug/page.tsx","what":"the screenshot button in the site's language","done":"aria-labelledby=\"bug-shot-label\"","pairs":[["          {user ? (\n            <label className=\"grid gap-1.5\">\n              <span className=\"text-sm font-semibold text-ink\">{t(\"report_bug_attach\")}</span>\n              <input type=\"file\" accept=\"image/*\" onChange={(e) => setFile(e.target.files?.[0] ?? null)} className=\"text-sm\" />\n              {file && <span className=\"text-sm font-semibold text-[#1e7a4f]\">{t(\"report_bug_attached\")}</span>}\n","          {user ? (\n            <div className=\"grid gap-1.5\">\n              <span id=\"bug-shot-label\" className=\"text-sm font-semibold text-ink\">{t(\"report_bug_attach\")}</span>\n              {/* the browser's own file button speaks the browser's language (\"Choose file\"): this one speaks the site's */}\n              <label className=\"flex cursor-pointer flex-wrap items-center gap-3\">\n                <input type=\"file\" accept=\"image/*\" aria-labelledby=\"bug-shot-label\" onChange={(e) => setFile(e.target.files?.[0] ?? null)} className=\"sr-only\" />\n                <span className=\"rounded-lg border border-line bg-chalk px-4 py-2 text-sm font-semibold text-navy\">{t(\"choose_file\")}</span>\n                <span className=\"min-w-0 truncate text-sm text-muted\" dir=\"auto\">{file ? file.name : t(\"no_file_chosen\")}</span>\n              </label>\n              {file && <span className=\"text-sm font-semibold text-[#1e7a4f]\">{t(\"report_bug_attached\")}</span>}\n"],["              {file && <span className=\"text-sm font-semibold text-[#1e7a4f]\">{t(\"report_bug_attached\")}</span>}\n            </label>\n          ) : (\n","              {file && <span className=\"text-sm font-semibold text-[#1e7a4f]\">{t(\"report_bug_attached\")}</span>}\n            </div>\n          ) : (\n"]]},{"file":"apps/web-storefront/app/support/page.tsx","what":"Support in the visitor's language","done":"t(\"support_notice\")","pairs":[["\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport { useAutoRefresh } from \"@/components/useAutoRefresh\";\nimport { useLocRouter } from \"@/components/useLocRouter\";\nimport Link from \"@/components/LocLink\";\nimport { useAuth, getAuthToken } from \"@/components/AuthProvider\";\nimport { SupportTicketSummary, fetchMyTickets, createSupportTicket } from \"@/lib/api\";\n\n// Real support tickets page (new) -- closes a real, confirmed gap:\n// this storefront had no support-ticket UI at all (the notification\n// bell's own resolveNotificationLink deliberately returned null for\n// ticket-type notifications specifically because of this). Two real\n// modes, same pattern as /returns:\n// - Logged in: a real list (GET /support/my-tickets), plus a form to\n//   open a new one.\n// - Not logged in: a real \"track your ticket\" lookup (ticket ID + the\n//   real email it was filed under), plus a form to open a new one as\n//   a guest -- mirrors the real guest-access fix in\n//   services/api/src/modules/support/routes.js (GET/POST\n//   /support/my-tickets/:id* were requireAuth only before this).\nexport default function SupportPage() {\n  const { user, isLoading: authLoading } = useAuth();\n  const router = useLocRouter();\n  const [tickets, setTickets] = useState<SupportTicketSummary[]>([]);\n  const [loadState, setLoadState] = useState<\"loading\" | \"ready\" | \"error\">(\"loading\");\n  const [error, setError] = useState<string | null>(null);\n\n  const [lookupTicketId, setLookupTicketId] = useState(\"\");\n  const [lookupEmail, setLookupEmail] = useState(\"\");\n\n  const [showNewForm, setShowNewForm] = useState(false);\n  const [newSubject, setNewSubject] = useState(\"\");\n  const [newMessage, setNewMessage] = useState(\"\");\n  const [newGuestEmail, setNewGuestEmail] = useState(\"\");\n  const [isSubmitting, setIsSubmitting] = useState(false);\n\n  useEffect(() => {\n    if (authLoading) return;\n    if (!user) {\n      Promise.resolve().then(() => setLoadState(\"ready\"));\n      return;\n    }\n    const token = getAuthToken();\n    if (!token) return;\n    fetchMyTickets(token)\n      .then((data) => { setTickets(data); setLoadState(\"ready\"); })\n      .catch((err) => { setError(err.message); setLoadState(\"error\"); });\n  }, [authLoading, user]);\n  useAutoRefresh(async () => { const token = getAuthToken(); if (!token) return; setTickets(await fetchMyTickets(token)); }, { enabled: !authLoading && !!user && loadState === \"ready\" });\n\n  const handleLookup = (e: React.FormEvent) => {\n    e.preventDefault();\n    if (!lookupTicketId.trim() || !lookupEmail.trim()) return;\n    router.push(`/support/${encodeURIComponent(lookupTicketId.trim())}?guestEmail=${encodeURIComponent(lookupEmail.trim())}`);\n  };\n\n  const handleCreate = async (e: React.FormEvent) => {\n    e.preventDefault();\n    if (!newSubject.trim() || !newMessage.trim()) return;\n    if (!user && !newGuestEmail.trim()) {\n      setError(\"Please provide an email so we can reach you.\");\n      return;\n    }\n    setIsSubmitting(true);\n    setError(null);\n    try {\n      const token = getAuthToken();\n      const result = await createSupportTicket(\n        { subject: newSubject.trim(), message: newMessage.trim() },\n        user ? { token: token || undefined } : { guestEmail: newGuestEmail.trim() }\n      );\n      if (user) {\n        router.push(`/support/${result.id}`);\n      } else {\n        router.push(`/support/${result.id}?guestEmail=${encodeURIComponent(newGuestEmail.trim())}`);\n      }\n    } catch (err) {\n      setError(err instanceof Error ? err.message : \"Failed to create ticket\");\n      setIsSubmitting(false);\n    }\n  };\n\n  if (authLoading || loadState === \"loading\") {\n    return <div className=\"mx-auto max-w-2xl px-6 py-16 text-muted\">Loading…</div>;\n  }\n\n  return (\n    <div className=\"mx-auto max-w-2xl px-6 py-16\">\n      <div className=\"flex items-center justify-between\">\n        <h1 className=\"font-display font-bold text-3xl\">Support</h1>\n        <button\n          onClick={() => setShowNewForm((v) => !v)}\n          className=\"text-sm font-semibold text-signal hover:text-signal-dark\"\n        >\n          {showNewForm ? \"Cancel\" : \"New ticket\"}\n        </button>\n      </div>\n\n      {error && <p className=\"mt-4 text-sm text-red-600\">{error}</p>}\n\n      {showNewForm && (\n        <form onSubmit={handleCreate} className=\"mt-6 space-y-3 rounded-lg border border-line bg-white p-4\">\n          <input\n            placeholder=\"Subject\"\n            value={newSubject}\n            onChange={(e) => setNewSubject(e.target.value)}\n            className=\"w-full rounded-md border border-line px-3 py-2 text-sm\"\n          />\n          <textarea\n            placeholder=\"How can we help?\"\n            value={newMessage}\n            onChange={(e) => setNewMessage(e.target.value)}\n            rows={4}\n            className=\"w-full rounded-md border border-line px-3 py-2 text-sm\"\n          />\n          {!user && (\n            <input\n              type=\"email\"\n              placeholder=\"Your email\"\n              value={newGuestEmail}\n              onChange={(e) => setNewGuestEmail(e.target.value)}\n              className=\"w-full rounded-md border border-line px-3 py-2 text-sm\"\n            />\n          )}\n          <button\n            type=\"submit\"\n            disabled={isSubmitting}\n            className=\"w-full rounded-md bg-signal px-6 py-3 text-on-signal font-semibold hover:bg-signal-dark transition-colors disabled:opacity-60\"\n          >\n            {isSubmitting ? \"Sending…\" : \"Submit\"}\n          </button>\n        </form>\n      )}\n\n      {!user ? (\n        <div className=\"mt-8\">\n          <h2 className=\"font-display font-bold text-lg mb-2\">Track an existing ticket</h2>\n          <p className=\"text-sm text-muted mb-4\">\n            Enter your ticket ID (from your confirmation) and the email you used to file it.\n          </p>\n          <form onSubmit={handleLookup} className=\"space-y-3\">\n            <input\n              placeholder=\"e.g. T-1234\"\n              value={lookupTicketId}\n              onChange={(e) => setLookupTicketId(e.target.value)}\n              className=\"w-full rounded-md border border-line px-3 py-2 text-sm font-plate uppercase\"\n            />\n            <input\n              type=\"email\"\n              placeholder=\"Email\"\n              value={lookupEmail}\n              onChange={(e) => setLookupEmail(e.target.value)}\n              className=\"w-full rounded-md border border-line px-3 py-2 text-sm\"\n            />\n            <button\n              type=\"submit\"\n              className=\"w-full rounded-md border border-line px-6 py-3 font-semibold hover:border-ink transition-colors\"\n            >\n              Track ticket\n            </button>\n          </form>\n          <p className=\"mt-6 text-sm text-muted\">\n            Have an account?{\" \"}\n            <Link href=\"/login\" className=\"text-signal font-medium\">\n              Log in\n            </Link>{\" \"}\n            to see all your tickets in one place.\n          </p>\n        </div>\n      ) : (\n        <div className=\"mt-8\">\n          {loadState === \"ready\" && tickets.length === 0 ? (\n            <p className=\"text-muted\">No support tickets yet.</p>\n          ) : (\n            <div className=\"space-y-3\">\n              {tickets.map((t) => (\n                <Link\n                  key={t.id}\n                  href={`/support/${t.id}`}\n                  className=\"flex items-center justify-between rounded-lg border border-line bg-white p-4 hover:border-signal transition-colors\"\n                >\n                  <div>\n                    <p className=\"font-semibold text-sm\">{t.subject}</p>\n                    <p className=\"text-xs text-muted mt-1\">{t.id}{t.orderId ? ` · Order ${t.orderId}` : \"\"}</p>\n                  </div>\n                  <span className=\"text-xs font-semibold uppercase text-signal\">\n                    {t.status.replace(/_/g, \" \")}\n                  </span>\n                </Link>\n              ))}\n            </div>\n          )}\n        </div>\n      )}\n    </div>\n  );\n}\n","\"use client\";\n\nimport { Suspense, useEffect, useState } from \"react\";\nimport { useSearchParams } from \"next/navigation\";\nimport Link from \"@/components/LocLink\";\nimport { getAuthToken, useAuth } from \"@/components/AuthProvider\";\nimport { useLang, useT } from \"@/components/LangProvider\";\nimport { useAutoRefresh } from \"@/components/useAutoRefresh\";\nimport { useLocRouter } from \"@/components/useLocRouter\";\nimport { createSupportTicket, fetchMyTickets, type SupportTicketSummary } from \"@/lib/api\";\nimport { statusLabel } from \"@/lib/orders\";\n\nconst EMAIL = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\nconst OPEN = [\"open\", \"in_progress\"];\nconst DONE = [\"resolved\", \"closed\"];\n\n// Support, like the app's screen, in the visitor's language: a signed-in buyer sees their tickets (how many, how many are open and resolved, and each with its\n// status) and opens a new one with the button; a guest opens one with their email, or tracks one with its ID and email. A ticket about an order (?orderId=)\n// opens the form at once and carries the order.\nfunction Support() {\n  const { user, isLoading: authLoading } = useAuth();\n  const lang = useLang();\n  const t = useT();\n  const router = useLocRouter();\n  const orderId = useSearchParams().get(\"orderId\");\n  const [tickets, setTickets] = useState<SupportTicketSummary[]>([]);\n  const [loadState, setLoadState] = useState<\"loading\" | \"ready\" | \"error\">(\"loading\");\n  const [loadError, setLoadError] = useState<string | null>(null);\n  const [showForm, setShowForm] = useState(!!orderId);\n  const [subject, setSubject] = useState(\"\");\n  const [message, setMessage] = useState(\"\");\n  const [guestEmail, setGuestEmail] = useState(\"\");\n  const [formError, setFormError] = useState<string | null>(null);\n  const [sending, setSending] = useState(false);\n  const [trackId, setTrackId] = useState(\"\");\n  const [trackEmail, setTrackEmail] = useState(\"\");\n  const [trackError, setTrackError] = useState<string | null>(null);\n\n  useEffect(() => {\n    if (authLoading) return;\n    if (!user) { Promise.resolve().then(() => setLoadState(\"ready\")); return; }\n    const token = getAuthToken();\n    if (!token) return;\n    fetchMyTickets(token).then((data) => { setTickets(data); setLoadState(\"ready\"); }).catch((err: Error) => { setLoadError(err.message); setLoadState(\"error\"); });\n  }, [authLoading, user]);\n  useAutoRefresh(async () => { const token = getAuthToken(); if (!token) return; setTickets(await fetchMyTickets(token)); }, { enabled: !authLoading && !!user && loadState === \"ready\" });\n\n  async function create(e: React.FormEvent) {\n    e.preventDefault();\n    if (!subject.trim() || !message.trim()) { setFormError(t(\"ticket_fill_both\")); return; }\n    if (!user && !guestEmail.trim()) { setFormError(t(\"ticket_need_email\")); return; }\n    if (!user && !EMAIL.test(guestEmail.trim())) { setFormError(t(\"please_enter_valid_email\")); return; }\n    setFormError(null); setSending(true);\n    try {\n      const token = getAuthToken();\n      const input = { subject: subject.trim(), message: message.trim(), ...(orderId ? { orderId } : {}) };\n      const result = await createSupportTicket(input, user ? { token: token ?? undefined } : { guestEmail: guestEmail.trim() });\n      router.push(user ? `/support/${result.id}` : `/support/${result.id}?guestEmail=${encodeURIComponent(guestEmail.trim())}`);\n    } catch (err) {\n      setFormError(err instanceof Error ? err.message : t(\"ticket_load_error\"));\n      setSending(false);\n    }\n  }\n\n  function track(e: React.FormEvent) {\n    e.preventDefault();\n    if (!trackId.trim() || !trackEmail.trim()) { setTrackError(t(\"ticket_fill_both\")); return; }\n    setTrackError(null);\n    router.push(`/support/${encodeURIComponent(trackId.trim())}?guestEmail=${encodeURIComponent(trackEmail.trim())}`);\n  }\n\n  if (authLoading || loadState === \"loading\") return <div className=\"mx-auto max-w-2xl px-4 py-10 text-muted sm:px-8\" aria-busy=\"true\">{t(\"search_loading\")}</div>;\n  const formOpen = showForm || !user;      // a guest gets the form straight away (there is no list to look at first)\n  const input = \"w-full rounded-lg border border-line px-3 py-2 text-[15px]\";\n  return (\n    <div className=\"mx-auto max-w-2xl px-4 py-10 sm:px-8\">\n      <div className=\"flex flex-wrap items-center justify-between gap-3\">\n        <h1 className=\"text-3xl font-bold tracking-tight text-navy\">{t(\"support_title\")}</h1>\n        {user && <button type=\"button\" onClick={() => setShowForm((v) => !v)} className=\"rounded-lg bg-signal px-4 py-2 text-sm font-semibold text-on-signal\">{showForm ? t(\"cancel\") : t(\"new_ticket_button\")}</button>}\n      </div>\n      <p className=\"mt-2 text-sm text-muted\">{t(\"support_notice\")}</p>\n\n      {formOpen && (\n        <form onSubmit={create} noValidate className=\"mt-6 grid gap-3 rounded-[14px] border border-line bg-white p-5\">\n          <h2 className=\"text-lg font-bold text-navy\">{t(\"new_ticket_title\")}</h2>\n          <label className=\"grid gap-1 text-sm font-semibold\">{t(\"subject_field\")}<input value={subject} onChange={(e) => setSubject(e.target.value)} className={input} /></label>\n          <label className=\"grid gap-1 text-sm font-semibold\">{t(\"how_can_we_help\")}<textarea value={message} onChange={(e) => setMessage(e.target.value)} rows={4} className={input} /></label>\n          {!user && (\n            <div className=\"grid gap-1\"><label htmlFor=\"nt-email\" className=\"text-sm font-semibold\">{t(\"email_label\")}</label><input id=\"nt-email\" type=\"email\" dir=\"ltr\" value={guestEmail} onChange={(e) => setGuestEmail(e.target.value)} className={input} /></div>\n          )}\n          {formError && <p role=\"alert\" className=\"text-sm font-semibold text-[#a12a21]\">{formError}</p>}\n          <button type=\"submit\" disabled={sending} className=\"justify-self-start rounded-lg bg-signal px-5 py-2.5 font-semibold text-on-signal disabled:opacity-60\">{sending ? t(\"sending\") : t(\"send_button\")}</button>\n        </form>\n      )}\n\n      {!user ? (\n        <section className=\"mt-8 rounded-[14px] border border-line bg-white p-5\">\n          <h2 className=\"text-lg font-bold text-navy\">{t(\"track_a_ticket\")}</h2>\n          <p className=\"mt-1 text-sm text-muted\">{t(\"track_ticket_help\")}</p>\n          <form onSubmit={track} noValidate className=\"mt-4 grid gap-3\">\n            <label className=\"grid gap-1 text-sm font-semibold\">{t(\"ticket_id_field\")}<input value={trackId} onChange={(e) => setTrackId(e.target.value)} dir=\"ltr\" placeholder=\"T-1234\" className={`${input} font-plate uppercase`} /></label>\n            <div className=\"grid gap-1\"><label htmlFor=\"tk-email\" className=\"text-sm font-semibold\">{t(\"email_label\")}</label><input id=\"tk-email\" type=\"email\" dir=\"ltr\" value={trackEmail} onChange={(e) => setTrackEmail(e.target.value)} className={input} /></div>\n            {trackError && <p role=\"alert\" className=\"text-sm font-semibold text-[#a12a21]\">{trackError}</p>}\n            <button type=\"submit\" className=\"justify-self-start rounded-lg border border-line px-5 py-2.5 font-semibold hover:border-ink\">{t(\"track_button\")}</button>\n          </form>\n          <p className=\"mt-4 text-sm text-muted\">{t(\"tickets_login\")}: <Link href=\"/login\" className=\"font-semibold text-navy underline underline-offset-4\">{t(\"sign_in\")}</Link></p>\n        </section>\n      ) : (\n        <section className=\"mt-8\">\n          {loadState === \"error\" && <p role=\"alert\" className=\"text-sm font-semibold text-[#a12a21]\">{t(\"tickets_load_error\")} {loadError}</p>}\n          <div className=\"grid grid-cols-3 gap-3\">\n            {([[tickets.length, \"total_tickets\"], [tickets.filter((x) => OPEN.includes(x.status)).length, \"open_requests\"], [tickets.filter((x) => DONE.includes(x.status)).length, \"status_resolved\"]] as const).map(([n, key]) => (\n              <div key={key} className=\"rounded-[14px] border border-line bg-white p-4\"><p className=\"text-2xl font-extrabold text-navy\">{n}</p><p className=\"text-sm font-semibold text-muted\">{t(key)}</p></div>\n            ))}\n          </div>\n          {loadState === \"ready\" && tickets.length === 0 ? (\n            <p className=\"mt-6 text-muted\">{t(\"tickets_empty\")}</p>\n          ) : (\n            <ul className=\"mt-6 grid gap-3\">\n              {tickets.map((x) => (\n                <li key={x.id}>\n                  <Link href={`/support/${x.id}`} className=\"flex items-center justify-between gap-3 rounded-[14px] border border-line bg-white p-4 hover:border-navy\">\n                    <span className=\"min-w-0\"><span dir=\"auto\" className=\"block font-semibold\">{x.subject}</span><span className=\"block text-xs text-muted\" dir=\"ltr\">{x.id}{x.orderId ? ` · ${x.orderId}` : \"\"}</span></span>\n                    <span className=\"shrink-0 rounded-full bg-[#fff4d6] px-3 py-1 text-xs font-bold text-navy\">{statusLabel(lang, x.status)}</span>\n                  </Link>\n                </li>\n              ))}\n            </ul>\n          )}\n        </section>\n      )}\n    </div>\n  );\n}\n\nexport default function SupportPage() {\n  return <Suspense fallback={null}><Support /></Suspense>;\n}\n"]]},{"file":"apps/web-storefront/app/support/[id]/page.tsx","what":"a ticket's conversation in the visitor's language","done":"t(\"was_resolution_helpful\")","pairs":[["\"use client\";\n\nimport { Suspense, useEffect, useState } from \"react\";\nimport { useParams, useSearchParams } from \"next/navigation\";\nimport Link from \"@/components/LocLink\";\nimport { useAuth, getAuthToken } from \"@/components/AuthProvider\";\nimport { SupportTicketDetail, fetchSupportTicket, sendSupportTicketMessage } from \"@/lib/api\";\n\n// Real support ticket detail + thread (new). Requires the same real\n// <Suspense> boundary around useSearchParams() as the signup,\n// checkout confirmation, and returns pages already established (a\n// real production build fails outright without one).\nfunction SupportTicketContent() {\n  const params = useParams();\n  const ticketId = params.id as string;\n  const searchParams = useSearchParams();\n  const urlGuestEmail = searchParams.get(\"guestEmail\");\n\n  const { user, isLoading: authLoading } = useAuth();\n  const [guestEmailInput, setGuestEmailInput] = useState(urlGuestEmail || \"\");\n  const [activeGuestEmail, setActiveGuestEmail] = useState(urlGuestEmail);\n\n  const [ticket, setTicket] = useState<SupportTicketDetail | null>(null);\n  const [loadState, setLoadState] = useState<\"loading\" | \"ready\" | \"error\" | \"needs-email\">(\"loading\");\n  const [error, setError] = useState<string | null>(null);\n  const [replyText, setReplyText] = useState(\"\");\n  const [isSending, setIsSending] = useState(false);\n\n  const load = () => {\n    const token = getAuthToken();\n    if (!token && !activeGuestEmail) {\n      setLoadState(\"needs-email\");\n      return;\n    }\n    setLoadState(\"loading\");\n    fetchSupportTicket(ticketId, { token: token || undefined, guestEmail: activeGuestEmail || undefined })\n      .then((data) => { setTicket(data); setLoadState(\"ready\"); })\n      .catch((err) => { setError(err.message); setLoadState(\"error\"); });\n  };\n\n  useEffect(() => {\n    if (authLoading) return;\n    load();\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [authLoading, user, activeGuestEmail, ticketId]);\n\n  const handleEmailSubmit = (e: React.FormEvent) => {\n    e.preventDefault();\n    if (!guestEmailInput.trim()) return;\n    setActiveGuestEmail(guestEmailInput.trim());\n  };\n\n  const handleReply = async (e: React.FormEvent) => {\n    e.preventDefault();\n    if (!replyText.trim()) return;\n    setIsSending(true);\n    try {\n      const token = getAuthToken();\n      await sendSupportTicketMessage(ticketId, replyText.trim(), { token: token || undefined, guestEmail: activeGuestEmail || undefined });\n      setReplyText(\"\");\n      load();\n    } catch (err) {\n      setError(err instanceof Error ? err.message : \"Failed to send message\");\n    } finally {\n      setIsSending(false);\n    }\n  };\n\n  if (authLoading || loadState === \"loading\") {\n    return <div className=\"mx-auto max-w-2xl px-6 py-16 text-muted\">Loading…</div>;\n  }\n\n  if (loadState === \"needs-email\") {\n    return (\n      <div className=\"mx-auto max-w-2xl px-6 py-16\">\n        <h1 className=\"font-display font-bold text-3xl\">{ticketId}</h1>\n        <p className=\"mt-2 text-muted\">\n          Enter the email this ticket was filed under to view it.\n        </p>\n        <form onSubmit={handleEmailSubmit} className=\"mt-6 flex gap-2\">\n          <input\n            type=\"email\"\n            required\n            value={guestEmailInput}\n            onChange={(e) => setGuestEmailInput(e.target.value)}\n            className=\"flex-1 rounded-md border border-line px-3 py-2 text-sm\"\n            placeholder=\"you@example.com\"\n          />\n          <button type=\"submit\" className=\"rounded-md bg-signal px-5 py-2 text-sm text-on-signal font-semibold hover:bg-signal-dark transition-colors\">\n            View\n          </button>\n        </form>\n      </div>\n    );\n  }\n\n  if (loadState === \"error\" || !ticket) {\n    return (\n      <div className=\"mx-auto max-w-2xl px-6 py-16\">\n        <h1 className=\"font-display font-bold text-3xl\">{ticketId}</h1>\n        <p className=\"mt-4 text-sm text-red-600\">{error || \"Ticket not found.\"}</p>\n        <Link href=\"/support\" className=\"mt-6 inline-block text-signal font-medium\">\n          Back to support\n        </Link>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"mx-auto max-w-2xl px-6 py-16\">\n      <Link href=\"/support\" className=\"text-sm text-muted hover:text-ink\">\n        ← Back to support\n      </Link>\n\n      <div className=\"mt-4 flex items-center justify-between\">\n        <h1 className=\"font-display font-bold text-2xl\">{ticket.subject}</h1>\n        <span className=\"text-xs font-semibold uppercase text-signal\">{ticket.status.replace(/_/g, \" \")}</span>\n      </div>\n      {ticket.orderId && <p className=\"mt-1 text-sm text-muted\">Order {ticket.orderId}</p>}\n\n      <div className=\"mt-6 space-y-3\">\n        {ticket.messages.map((m, i) => (\n          <div key={i} className={`flex ${m.senderRole === \"admin\" ? \"justify-start\" : \"justify-end\"}`}>\n            <div className={`max-w-[75%] rounded-lg px-4 py-2 text-sm ${m.senderRole === \"admin\" ? \"bg-chalk text-ink\" : \"bg-ink text-white\"}`}>\n              {m.message}\n            </div>\n          </div>\n        ))}\n      </div>\n\n      {error && <p className=\"mt-4 text-sm text-red-600\">{error}</p>}\n\n      <form onSubmit={handleReply} className=\"mt-6 flex gap-2\">\n        <input\n          type=\"text\"\n          value={replyText}\n          onChange={(e) => setReplyText(e.target.value)}\n          placeholder=\"Type a message…\"\n          className=\"flex-1 rounded-md border border-line px-3 py-2 text-sm\"\n        />\n        <button\n          type=\"submit\"\n          disabled={isSending}\n          className=\"rounded-md bg-signal px-5 py-2 text-sm text-on-signal font-semibold hover:bg-signal-dark transition-colors disabled:opacity-60\"\n        >\n          {isSending ? \"Sending…\" : \"Send\"}\n        </button>\n      </form>\n    </div>\n  );\n}\n\nexport default function SupportTicketPage() {\n  return (\n    <Suspense fallback={<div className=\"mx-auto max-w-2xl px-6 py-16 text-muted\">Loading…</div>}>\n      <SupportTicketContent />\n    </Suspense>\n  );\n}\n","\"use client\";\n\nimport { Suspense, useCallback, useEffect, useState } from \"react\";\nimport { useParams, useSearchParams } from \"next/navigation\";\nimport Link from \"@/components/LocLink\";\nimport { getAuthToken, useAuth } from \"@/components/AuthProvider\";\nimport { useLang, useT } from \"@/components/LangProvider\";\nimport { useLocRouter } from \"@/components/useLocRouter\";\nimport { fetchSupportTicket, sendSupportTicketMessage, submitTicketFeedback, type SupportTicketDetail } from \"@/lib/api\";\nimport { statusLabel } from \"@/lib/orders\";\n\nconst REFRESH_MS = 5_000;      // the conversation refreshes every 5 seconds while it is open, like the app\n\n// One support ticket, like the app's screen, in the visitor's language: the conversation (the Leap team's messages on one side, the buyer's on the other),\n// a reply box, and once the ticket is resolved or closed, \"Was this resolution helpful?\" (asked once). A guest without the email in the address is asked for it.\nfunction Ticket({ ticketId }: { ticketId: string }) {\n  const { user, isLoading: authLoading } = useAuth();\n  const lang = useLang();\n  const t = useT();\n  const router = useLocRouter();\n  const guestEmail = useSearchParams().get(\"guestEmail\");\n  const token = user ? getAuthToken() : null;\n  const canSee = !!token || !!guestEmail;\n  const auth = { token: token ?? undefined, guestEmail: token ? undefined : guestEmail ?? undefined };\n  const [ticket, setTicket] = useState<SupportTicketDetail | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [gateEmail, setGateEmail] = useState(\"\");\n  const [reply, setReply] = useState(\"\");\n  const [sending, setSending] = useState(false);\n  const [replyError, setReplyError] = useState<string | null>(null);\n  const [feedbackError, setFeedbackError] = useState<string | null>(null);\n  const [thanked, setThanked] = useState(false);\n\n  const load = useCallback(async () => {\n    try { setTicket(await fetchSupportTicket(ticketId, { token: token ?? undefined, guestEmail: token ? undefined : guestEmail ?? undefined })); setError(null); }\n    catch (err) { setError(err instanceof Error ? err.message : String(err)); }\n    finally { setLoading(false); }\n  }, [ticketId, token, guestEmail]);\n  useEffect(() => {\n    if (authLoading || !canSee) return undefined;\n    void load();\n    const timer = setInterval(() => { void load(); }, REFRESH_MS);\n    return () => clearInterval(timer);\n  }, [authLoading, canSee, load]);\n\n  if (authLoading) return <div className=\"mx-auto max-w-3xl px-4 py-10 sm:px-8\" aria-busy=\"true\">{t(\"search_loading\")}</div>;\n  if (!canSee) {\n    return (\n      <div className=\"mx-auto max-w-3xl px-4 py-12 sm:px-8\">\n        <h1 className=\"mb-4 text-2xl font-bold text-navy\">{t(\"ticket_word\")} {ticketId}</h1>\n        <form noValidate onSubmit={(e) => { e.preventDefault(); if (gateEmail.trim()) router.push(`/support/${encodeURIComponent(ticketId)}?guestEmail=${encodeURIComponent(gateEmail.trim())}`); }} className=\"grid max-w-md gap-3 rounded-[14px] border border-line bg-white p-5\">\n          <p className=\"text-sm text-muted\">{t(\"ticket_email_prompt\")}</p>\n          <label className=\"grid gap-1 text-sm font-semibold\">{t(\"email_label\")}<input type=\"email\" dir=\"ltr\" value={gateEmail} onChange={(e) => setGateEmail(e.target.value)} className=\"rounded-lg border border-line px-3 py-2 text-[15px]\" /></label>\n          <button type=\"submit\" className=\"justify-self-start rounded-lg bg-signal px-5 py-2 font-semibold text-on-signal\">{t(\"view_button\")}</button>\n        </form>\n      </div>\n    );\n  }\n  if (loading && !ticket) return <div className=\"mx-auto max-w-3xl px-4 py-10 text-muted sm:px-8\" aria-busy=\"true\">{t(\"search_loading\")}</div>;\n  if (!ticket) {\n    const notFound = /not found|غير موجود/i.test(error ?? \"\");\n    return (\n      <div className=\"mx-auto max-w-3xl px-4 py-12 sm:px-8\">\n        {notFound ? <h1 className=\"text-2xl font-bold\">{t(\"order_not_found\")}</h1> : <p role=\"alert\" className=\"font-semibold text-[#a12a21]\">{t(\"ticket_load_error\")} {error}</p>}\n        <p className=\"mt-3\"><Link href=\"/support\" className=\"font-bold text-navy underline underline-offset-4\">{t(\"back_to_tickets\")}</Link></p>\n      </div>\n    );\n  }\n  const askFeedback = (ticket.status === \"resolved\" || ticket.status === \"closed\") && (ticket.resolutionHelpful === null || ticket.resolutionHelpful === undefined) && !thanked;\n  async function answer(helpful: boolean) {\n    setFeedbackError(null);\n    try { await submitTicketFeedback(ticketId, helpful, auth); setThanked(true); void load(); }\n    catch (err) { setFeedbackError(err instanceof Error ? err.message : String(err)); }\n  }\n  async function send(e: React.FormEvent) {\n    e.preventDefault();\n    const text = reply.trim();\n    if (!text || sending) return;\n    setSending(true); setReplyError(null);\n    try { await sendSupportTicketMessage(ticketId, text, auth); setReply(\"\"); await load(); }\n    catch (err) { setReplyError(err instanceof Error ? err.message : String(err)); }\n    finally { setSending(false); }\n  }\n  return (\n    <div className=\"mx-auto max-w-3xl px-4 py-10 sm:px-8\">\n      <p className=\"mb-2\"><Link href=\"/support\" className=\"text-sm font-semibold text-navy underline underline-offset-4\">{t(\"back_to_tickets\")}</Link></p>\n      <div className=\"mb-6 flex flex-wrap items-start justify-between gap-3\">\n        <div>\n          <h1 dir=\"auto\" className=\"text-2xl font-bold tracking-tight text-navy\">{ticket.subject}</h1>\n          {ticket.orderId && <p className=\"text-sm text-muted\">{t(\"for_order\")} <span className=\"font-plate font-semibold\" dir=\"ltr\">{ticket.orderId}</span></p>}\n        </div>\n        <span className=\"rounded-full bg-[#fff4d6] px-3 py-1 text-xs font-bold text-navy\">{statusLabel(lang, ticket.status)}</span>\n      </div>\n      <ul className=\"grid gap-3\">\n        {ticket.messages.map((msg, i) => (\n          <li key={i} className={`flex ${msg.senderRole === \"buyer\" ? \"justify-end\" : \"justify-start\"}`}>\n            <p dir=\"auto\" className={`max-w-[75%] whitespace-pre-wrap rounded-[14px] px-4 py-2.5 text-[15px] ${msg.senderRole === \"buyer\" ? \"bg-navy text-white\" : \"border border-line bg-white text-ink\"}`}>{msg.message}</p>\n          </li>\n        ))}\n      </ul>\n      {askFeedback && (\n        <div className=\"mt-6 rounded-[14px] border border-line bg-white p-4\">\n          <p className=\"font-semibold text-navy\">{t(\"was_resolution_helpful\")}</p>\n          <div className=\"mt-3 flex gap-2\">\n            <button type=\"button\" onClick={() => void answer(true)} className=\"rounded-lg bg-signal px-5 py-2 font-semibold text-on-signal\">{t(\"yes\")}</button>\n            <button type=\"button\" onClick={() => void answer(false)} className=\"rounded-lg border border-line px-5 py-2 font-semibold\">{t(\"no_word\")}</button>\n          </div>\n          {feedbackError && <p role=\"alert\" className=\"mt-2 text-sm font-semibold text-[#a12a21]\">{feedbackError}</p>}\n        </div>\n      )}\n      {thanked && <p role=\"status\" className=\"mt-6 font-semibold text-[#1e7a4f]\">{t(\"thanks_feedback\")}</p>}\n      <form onSubmit={send} className=\"mt-6 flex gap-2\">\n        <input aria-label={t(\"type_message\")} placeholder={t(\"type_message\")} value={reply} onChange={(e) => setReply(e.target.value)} className=\"min-w-0 flex-1 rounded-lg border border-line px-3 py-2 text-[15px]\" />\n        <button type=\"submit\" disabled={sending} className=\"rounded-lg bg-signal px-5 py-2 font-semibold text-on-signal disabled:opacity-60\">{sending ? t(\"sending\") : t(\"send_button\")}</button>\n      </form>\n      {replyError && <p role=\"alert\" className=\"mt-2 text-sm font-semibold text-[#a12a21]\">{replyError}</p>}\n    </div>\n  );\n}\n\nexport default function SupportTicketPage() {\n  const { id } = useParams<{ id: string }>();\n  return <Suspense fallback={null}><Ticket ticketId={id} /></Suspense>;\n}\n"]]},{"file":"apps/web-storefront/app/returns/page.tsx","what":"My returns in the visitor's language","done":"t(\"returns_empty\")","pairs":[["\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport { useAutoRefresh } from \"@/components/useAutoRefresh\";\nimport { useLocRouter } from \"@/components/useLocRouter\";\nimport Link from \"@/components/LocLink\";\nimport { useAuth, getAuthToken } from \"@/components/AuthProvider\";\nimport { ReturnCaseSummary, fetchMyReturnCases } from \"@/lib/api\";\n\n// Real returns page (new) -- the last remaining gap from the original\n// storefront list. Two real modes, not one screen pretending to cover\n// both:\n// - Logged in: a real list, same GET /returns/my-cases the mobile app\n//   already uses.\n// - Not logged in: a real \"track your return\" lookup (case ID + the\n//   real email it was filed under) -- closes a genuine, separate gap\n//   found this session: a guest who filed a return previously had NO\n//   way to ever check on it again (GET /returns/my-cases/:id was\n//   requireAuth only). Now guest-accessible via a matching email,\n//   mirroring GET /order/:id's own established pattern exactly.\nexport default function ReturnsPage() {\n  const { user, isLoading: authLoading } = useAuth();\n  const router = useLocRouter();\n  const [cases, setCases] = useState<ReturnCaseSummary[]>([]);\n  const [loadState, setLoadState] = useState<\"loading\" | \"ready\" | \"error\">(\"loading\");\n  const [error, setError] = useState<string | null>(null);\n\n  const [lookupCaseId, setLookupCaseId] = useState(\"\");\n  const [lookupEmail, setLookupEmail] = useState(\"\");\n\n  useEffect(() => {\n    if (authLoading) return;\n    if (!user) {\n      Promise.resolve().then(() => setLoadState(\"ready\"));\n      return;\n    }\n    const token = getAuthToken();\n    if (!token) return;\n    fetchMyReturnCases(token)\n      .then((data) => { setCases(data); setLoadState(\"ready\"); })\n      .catch((err) => { setError(err.message); setLoadState(\"error\"); });\n  }, [authLoading, user]);\n  useAutoRefresh(async () => { const token = getAuthToken(); if (!token) return; setCases(await fetchMyReturnCases(token)); }, { enabled: !authLoading && !!user && loadState === \"ready\" });\n\n  const handleLookup = (e: React.FormEvent) => {\n    e.preventDefault();\n    if (!lookupCaseId.trim() || !lookupEmail.trim()) return;\n    router.push(`/returns/${encodeURIComponent(lookupCaseId.trim())}?guestEmail=${encodeURIComponent(lookupEmail.trim())}`);\n  };\n\n  if (authLoading || loadState === \"loading\") {\n    return <div className=\"mx-auto max-w-2xl px-6 py-16 text-muted\">Loading…</div>;\n  }\n\n  if (!user) {\n    return (\n      <div className=\"mx-auto max-w-2xl px-6 py-16\">\n        <h1 className=\"font-display font-bold text-3xl\">Track a return</h1>\n        <p className=\"mt-2 text-muted\">\n          Enter your return case ID (from your confirmation) and the email you used to file it.\n        </p>\n        <form onSubmit={handleLookup} className=\"mt-8 space-y-4\">\n          <div>\n            <label className=\"block text-sm font-medium mb-1\">Return case ID</label>\n            <input\n              type=\"text\"\n              required\n              value={lookupCaseId}\n              onChange={(e) => setLookupCaseId(e.target.value)}\n              placeholder=\"e.g. RC-1234\"\n              className=\"w-full rounded-md border border-line px-3 py-2 text-sm font-plate uppercase\"\n            />\n          </div>\n          <div>\n            <label className=\"block text-sm font-medium mb-1\">Email</label>\n            <input\n              type=\"email\"\n              required\n              value={lookupEmail}\n              onChange={(e) => setLookupEmail(e.target.value)}\n              className=\"w-full rounded-md border border-line px-3 py-2 text-sm\"\n            />\n          </div>\n          <button\n            type=\"submit\"\n            className=\"w-full rounded-md bg-signal px-6 py-3 text-on-signal font-semibold hover:bg-signal-dark transition-colors\"\n          >\n            Track return\n          </button>\n        </form>\n        <p className=\"mt-6 text-sm text-muted\">\n          Have an account?{\" \"}\n          <Link href=\"/login\" className=\"text-signal font-medium\">\n            Log in\n          </Link>{\" \"}\n          to see all your returns in one place.\n        </p>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"mx-auto max-w-2xl px-6 py-16\">\n      <h1 className=\"font-display font-bold text-3xl\">My returns</h1>\n\n      {error && <p className=\"mt-4 text-sm text-red-600\">{error}</p>}\n\n      {loadState === \"ready\" && cases.length === 0 ? (\n        <p className=\"mt-8 text-muted\">No return requests yet.</p>\n      ) : (\n        <div className=\"mt-8 space-y-3\">\n          {cases.map((c) => (\n            <Link\n              key={c.id}\n              href={`/returns/${c.id}`}\n              className=\"flex items-center justify-between rounded-lg border border-line bg-white p-4 hover:border-signal transition-colors\"\n            >\n              <div>\n                <p className=\"font-semibold text-sm\">{c.id}</p>\n                <p className=\"text-xs text-muted mt-1\">{c.reason} · Order {c.orderId}</p>\n              </div>\n              <span className=\"text-xs font-semibold uppercase text-signal\">\n                {c.status.replace(/_/g, \" \")}\n              </span>\n            </Link>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n","\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport Link from \"@/components/LocLink\";\nimport { getAuthToken, useAuth } from \"@/components/AuthProvider\";\nimport { useLang, useT } from \"@/components/LangProvider\";\nimport { useAutoRefresh } from \"@/components/useAutoRefresh\";\nimport { useLocRouter } from \"@/components/useLocRouter\";\nimport { fetchMyReturnCases, type ReturnCaseSummary } from \"@/lib/api\";\nimport { statusLabel } from \"@/lib/orders\";\n\n// My returns, like the app's screen, in the visitor's language: a signed-in buyer sees every return request with its reason, its order and its status; a guest\n// tracks one with its case ID and the email it was filed under (and is told that signing in shows them all).\nexport default function ReturnsPage() {\n  const { user, isLoading: authLoading } = useAuth();\n  const lang = useLang();\n  const t = useT();\n  const router = useLocRouter();\n  const [cases, setCases] = useState<ReturnCaseSummary[]>([]);\n  const [loadState, setLoadState] = useState<\"loading\" | \"ready\" | \"error\">(\"loading\");\n  const [loadError, setLoadError] = useState<string | null>(null);\n  const [caseId, setCaseId] = useState(\"\");\n  const [email, setEmail] = useState(\"\");\n  const [trackError, setTrackError] = useState<string | null>(null);\n\n  useEffect(() => {\n    if (authLoading) return;\n    if (!user) { Promise.resolve().then(() => setLoadState(\"ready\")); return; }\n    const token = getAuthToken();\n    if (!token) return;\n    fetchMyReturnCases(token).then((data) => { setCases(data); setLoadState(\"ready\"); }).catch((err: Error) => { setLoadError(err.message); setLoadState(\"error\"); });\n  }, [authLoading, user]);\n  useAutoRefresh(async () => { const token = getAuthToken(); if (!token) return; setCases(await fetchMyReturnCases(token)); }, { enabled: !authLoading && !!user && loadState === \"ready\" });\n\n  function track(e: React.FormEvent) {\n    e.preventDefault();\n    if (!caseId.trim() || !email.trim()) { setTrackError(t(\"ticket_fill_both\")); return; }\n    setTrackError(null);\n    router.push(`/returns/${encodeURIComponent(caseId.trim())}?guestEmail=${encodeURIComponent(email.trim())}`);\n  }\n\n  if (authLoading || loadState === \"loading\") return <div className=\"mx-auto max-w-2xl px-4 py-10 text-muted sm:px-8\" aria-busy=\"true\">{t(\"search_loading\")}</div>;\n  const input = \"w-full rounded-lg border border-line px-3 py-2 text-[15px]\";\n\n  if (!user) {\n    return (\n      <div className=\"mx-auto max-w-2xl px-4 py-10 sm:px-8\">\n        <h1 className=\"text-3xl font-bold tracking-tight text-navy\">{t(\"track_a_return\")}</h1>\n        <p className=\"mt-2 text-muted\">{t(\"track_return_help\")}</p>\n        <form onSubmit={track} noValidate className=\"mt-6 grid gap-3 rounded-[14px] border border-line bg-white p-5\">\n          <label className=\"grid gap-1 text-sm font-semibold\">{t(\"return_case_id_field\")}<input value={caseId} onChange={(e) => setCaseId(e.target.value)} dir=\"ltr\" placeholder=\"RC-1234\" className={`${input} font-plate uppercase`} /></label>\n          <label className=\"grid gap-1 text-sm font-semibold\">{t(\"email_label\")}<input type=\"email\" dir=\"ltr\" value={email} onChange={(e) => setEmail(e.target.value)} className={input} /></label>\n          {trackError && <p role=\"alert\" className=\"text-sm font-semibold text-[#a12a21]\">{trackError}</p>}\n          <button type=\"submit\" className=\"justify-self-start rounded-lg bg-signal px-5 py-2.5 font-semibold text-on-signal\">{t(\"track_button\")}</button>\n        </form>\n        <p className=\"mt-6 text-sm\"><Link href=\"/login\" className=\"font-semibold text-navy underline underline-offset-4\">{t(\"returns_login\")}</Link></p>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"mx-auto max-w-2xl px-4 py-10 sm:px-8\">\n      <h1 className=\"text-3xl font-bold tracking-tight text-navy\">{t(\"my_returns_title\")}</h1>\n      {loadState === \"error\" && <p role=\"alert\" className=\"mt-4 text-sm font-semibold text-[#a12a21]\">{t(\"returns_load_error\")} {loadError}</p>}\n      {loadState === \"ready\" && cases.length === 0 ? (\n        <p className=\"mt-6 text-muted\">{t(\"returns_empty\")}</p>\n      ) : (\n        <ul className=\"mt-6 grid gap-3\">\n          {cases.map((c) => (\n            <li key={c.id}>\n              <Link href={`/returns/${c.id}`} className=\"flex items-center justify-between gap-3 rounded-[14px] border border-line bg-white p-4 hover:border-navy\">\n                <span className=\"min-w-0\">\n                  <span dir=\"auto\" className=\"block font-semibold\">{c.reason}</span>\n                  <span className=\"block text-xs text-muted\"><span dir=\"ltr\">{c.id}</span> · {t(\"for_order\")} <span className=\"font-plate\" dir=\"ltr\">{c.orderId}</span></span>\n                </span>\n                <span className=\"shrink-0 rounded-full bg-[#fff4d6] px-3 py-1 text-xs font-bold text-navy\">{statusLabel(lang, c.status)}</span>\n              </Link>\n            </li>\n          ))}\n        </ul>\n      )}\n    </div>\n  );\n}\n"]]}],"created":[]};
const once = (s, a) => s.split(a).length === 2;
const plan = [];
let problems = 0;
for (const e of DATA.anchored) {
  const p = path.join(root, e.file);
  if (!fs.existsSync(p)) { console.log(`MISSING   ${e.file}: not found. Run this from D:\\LEAP-MARKETPLACE.`); problems++; continue; }
  const s = fs.readFileSync(p, 'utf8');
  const c = (x) => (s.includes('\r\n') ? x.replace(/\r?\n/g, '\r\n') : x);
  if (s.includes(c(e.done))) { console.log(`already   ${e.file}: ${e.what}`); continue; }
  let out = s;
  for (const [a0, b0] of e.pairs) { const a = c(a0), b = c(b0); if (!once(out, a)) { out = null; break; } out = out.replace(a, () => b); }
  if (out === null) { console.log(`REFUSED   ${e.file}: its text is not what this patch expects, so nothing was changed. Send this file.`); problems++; continue; }
  plan.push({ file: e.file, what: e.what, before: s, after: out });
}
for (const e of DATA.created) {
  const p = path.join(root, e.file);
  if (!fs.existsSync(path.dirname(p))) { console.log(`MISSING   ${path.dirname(e.file)}: folder not found. Run this from D:\\LEAP-MARKETPLACE.`); problems++; continue; }
  if (fs.existsSync(p)) {
    const s = fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n');
    if (s === e.text) { console.log(`already   ${e.file}: ${e.what}`); continue; }
    console.log(`REFUSED   ${e.file}: a different file with this name is already there, so nothing was changed. Send this file.`); problems++; continue;
  }
  plan.push({ file: e.file, what: e.what, before: null, after: e.text });
}
if (problems > 0) { console.log('\nNothing was changed, because of the problem(s) above.'); process.exit(1); }
for (const c of plan) {
  if (write) {
    const p = path.join(root, c.file);
    if (c.before !== null) fs.writeFileSync(`${p}.before-support-arabic`, c.before);
    fs.writeFileSync(p, c.after);
    console.log(`${c.before === null ? 'created ' : 'patched '}  ${c.file}: ${c.what}`);
  } else console.log(`would     ${c.file}: ${c.what}`);
}
if (!write && plan.length) console.log('\nDry run only. Add --write to apply.');
if (write && plan.length) console.log('\nDone. Refresh the website (Ctrl+F5).');
